using System;
using System.IO;
using System.Linq;
using LogicLegends.Graph;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using Object=UnityEngine.Object;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    public static class ArchiveGraphPolish
    {
        const string Folder=ArchiveTopicSetup.Folder,Prefabs=Folder+"/Art/Prefabs/",Kit=Prefabs+"Archive_T09_Path_of_Connections.prefab";
        static Mesh cube,octagon,ring;static TMP_FontAsset font;static Material stone,gold,labels,energy,ink;
        [MenuItem("Tools/Logic Legends/Open Archive/Topics/Polish T9 Path of Connections")]
        public static string Apply(){
            if(EditorApplication.isPlayingOrWillChangePlaymode||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new InvalidOperationException("Use stopped Play Mode and a saved scene.");AuditSolo();var primitive=GameObject.CreatePrimitive(PrimitiveType.Cube);cube=primitive.GetComponent<MeshFilter>().sharedMesh;Object.DestroyImmediate(primitive);
            octagon=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_BeveledOctagon.asset");ring=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_InlayRing.asset");font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/RulesOfInferenceUI/InferenceBody.asset");stone=Mat("Archive_Topic_Stone");gold=Mat("Archive_Topic_BrassInlay");labels=Mat("Archive_Topic_WorldLabels");energy=ColorMat("Archive_T9_PathEnergy",ArchiveGraphPresentation.Available);ink=ColorMat("Archive_T9_Ink",new Color(.04f,.14f,.18f));
            var vertex=Vertex();var path=Path();var degree=Degree();var kit=PrefabUtility.LoadPrefabContents(Kit);
            try{var before=kit.GetComponentsInChildren<Collider>(true).Select(EditorJsonUtility.ToJson).ToArray();foreach(var old in kit.transform.Cast<Transform>().Where(t=>new[]{"T9_Visual_Identity","Mathematical_Inlay","Seal_Inlay"}.Contains(t.name)).ToArray())Object.DestroyImmediate(old.gameObject);var root=new GameObject("T9_Visual_Identity").transform;root.SetParent(kit.transform,false);
                var text=Text(root,"Graph_Entry_Inscription","START   →   WALK THE EDGES   →   CONFIRM AT GOAL",new Vector3(0,.09f,7),new Vector2(8.5f,.55f),3);text.transform.localRotation=Quaternion.Euler(90,180,0);text.color=new Color(.05f,.28f,.33f);
                var art=kit.GetComponent<ArchiveGraphPresentation>();if(art==null)art=kit.AddComponent<ArchiveGraphPresentation>();art.vertexPrefab=vertex;art.pathPrefab=path;art.degreePrefab=degree;art.arrowMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_T8_DirectedArrow.asset");art.energyMaterial=energy;art.sparkMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_RuleCrystal.asset");art.sparkMaterial=Mat("Archive_T1_Sparks");art.arrivalSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Assets/Sounds Effects/Small Sound Kit/Magic/Mgc_Ice_Arrow_Cast_01.wav");art.correctSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Graph/Correct.wav");art.incorrectSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Assets/Sounds Effects/Small Sound Kit/Magic/Mgc_Electric_Hit_01.wav");
                art.progressMarks=new Renderer[5];for(int i=0;i<5;i++){float x=(2-i)*.65f;Part(root,"Graph_Progress_Brass_"+i,octagon,gold,new Vector3(x,.07f,6.4f),new Vector3(.48f,.07f,.48f));art.progressMarks[i]=Part(root,"Graph_Progress_Seal_"+i,octagon,energy,new Vector3(x,.11f,6.4f),new Vector3(.33f,.025f,.33f)).GetComponent<Renderer>();}
                var station=kit.GetComponent<ArchiveTopicStation>();station.title.text="T9  GRAPHS\nPath of Connections";station.board.text="THE PATH OF CONNECTIONS\nGreen start · Gold goal\nRead the Book to begin.";station.GetComponentInChildren<ArchiveAnimatedBook>().bookRig.localScale=Vector3.one*.75f;
                if(!before.SequenceEqual(kit.GetComponentsInChildren<Collider>(true).Select(EditorJsonUtility.ToJson)))throw new InvalidOperationException("T9 collision changed.");PrefabUtility.SaveAsPrefabAsset(kit,Kit);
            }finally{PrefabUtility.UnloadPrefabContents(kit);}return "Saved T9 Path of Connections and three reusable ground-level graph props; original solo and island collision preserved.";
        }
        public static string AuditSolo(){var preview=EditorSceneManager.OpenPreviewScene("Assets/Scenes/Graph.unity");float seconds=0;GraphChallengeCatalog source=null;int managers=0;
            try{var found=preview.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<GraphStageManager>(true)).ToArray();managers=found.Length;if(managers!=1)throw new InvalidOperationException("Expected one current solo GraphStageManager.");var data=new SerializedObject(found[0]);seconds=data.FindProperty("countdownSeconds").floatValue;source=data.FindProperty("catalog").objectReferenceValue as GraphChallengeCatalog;}finally{EditorSceneManager.ClosePreviewScene(preview);}
            var archive=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(Folder+"/Archive_Topic_Catalog.asset");bool same=archive.graphs==source;var result=new{passed=seconds==600&&source!=null&&source.variantSets.Count==5&&source.variantSets.All(g=>g.variants.Count==10)&&same,sourceScene="Assets/Scenes/Graph.unity",controller="GraphStageManager",managers,startingSeconds=seconds,incorrectPenaltySeconds=10,sharedCatalog=same,sourceCatalog=AssetDatabase.GetAssetPath(source),groups=source.variantSets.Select(g=>new{type=g.variants[0].type.ToString(),variants=g.variants.Count}).ToArray(),adaptations=new[]{"Existing authoritative session; checkpointed runner, route and connecting-edge transaction","Uniformly fitted ground-level graph paths with no new collision or navigation blockers","Actual capsule-foot movement; directed edges and midpoint traversal required","Explicit runner claim/retry at the green start rune; no player teleport","Solo ten-minute remaining clock pauses only at solved Book gates","Wrong Confirm retains work and costs ten seconds; timeout keeps solved team progress"}};Directory.CreateDirectory(Folder+"/Testing/Reports");File.WriteAllText(Folder+"/Testing/Reports/T9SoloAudit.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));if(!result.passed)throw new InvalidOperationException("Current solo Graph configuration differs from expected.");return "Audited five Graph groups and fifty original variants.";
        }
        static GameObject Vertex(){var root=new GameObject("Archive_T9_VertexRune");Part(root.transform,"Vertex_Stone",octagon,stone,new Vector3(0,.06f,0),new Vector3(1.52f,.20f,1.52f));Part(root.transform,"Vertex_Inlay",ring,energy,new Vector3(0,.17f,0),Vector3.one*1.32f);Part(root.transform,"Vertex_Center",octagon,ink,new Vector3(0,.15f,0),new Vector3(1.05f,.02f,1.05f));Text(root.transform,"Vertex_Label","A\nSTART",new Vector3(0,.86f,0),new Vector2(1.8f,.75f),3.5f);return Save(root,"Archive_T9_VertexRune.prefab");}
        static GameObject Path(){var root=new GameObject("Archive_T9_PathSegment");Part(root.transform,"Stone_Path",cube,stone,new Vector3(0,.028f,0),new Vector3(.96f,.045f,1));Part(root.transform,"Path_Inlay",cube,energy,new Vector3(0,.055f,0),new Vector3(.09f,.008f,1));return Save(root,"Archive_T9_PathSegment.prefab");}
        static GameObject Degree(){var root=new GameObject("Archive_T9_DegreeSeal");Part(root.transform,"Degree_Stone",octagon,stone,new Vector3(0,.06f,0),new Vector3(.94f,.20f,.94f));Part(root.transform,"Choice_Inlay",ring,energy,new Vector3(0,.17f,0),Vector3.one*.8f);Text(root.transform,"Degree_Label","0",new Vector3(0,.70f,0),new Vector2(.8f,.65f),4);return Save(root,"Archive_T9_DegreeSeal.prefab");}
        static GameObject Save(GameObject root,string file){var asset=PrefabUtility.SaveAsPrefabAsset(root,Prefabs+file);Object.DestroyImmediate(root);return asset;}
        static Material Mat(string name)=>AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Art/Materials/"+name+".mat");
        static Material ColorMat(string name,Color c){var m=Mat(name);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Unlit")){name=name,enableInstancing=true};AssetDatabase.CreateAsset(m,Folder+"/Art/Materials/"+name+".mat");}m.SetColor("_BaseColor",c);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
        static TMP_Text Text(Transform parent,string name,string value,Vector3 pos,Vector2 size,float fontSize){var t=new GameObject(name).AddComponent<TextMeshPro>();t.transform.SetParent(parent,false);t.transform.localPosition=pos;t.rectTransform.sizeDelta=size;t.font=font;t.fontSharedMaterial=labels;t.text=value;t.fontSize=fontSize;t.enableAutoSizing=true;t.fontSizeMax=fontSize;t.fontSizeMin=fontSize-1;t.textWrappingMode=TextWrappingModes.NoWrap;t.richText=false;t.alignment=TextAlignmentOptions.Center;t.color=new Color(1,.94f,.79f);t.raycastTarget=false;return t;}
        static Transform Part(Transform parent,string name,Mesh mesh,Material material,Vector3 pos,Vector3 scale){var p=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer)).transform;p.SetParent(parent,false);p.localPosition=pos;p.localScale=scale;p.GetComponent<MeshFilter>().sharedMesh=mesh;p.GetComponent<MeshRenderer>().sharedMaterial=material;p.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;return p;}
    }
}
